SELECT c.FirstName, c.LastName, e.City
FROM Customer c
LEFT JOIN Employee e ON c.SupportRepId = e.EmployeeId;

SELECT t.Name AS TrackName, m.Name AS MediaTypeName
FROM Track t
JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId;

SELECT e1.LastName || ' ' || e1.FirstName AS EmployeeName, e2.FirstName AS ManagerFirstName
FROM Employee e1
JOIN Employee e2 ON e1.ReportsTo = e2.EmployeeId;
